#!/usr/bin/env node
'use strict';

// Generates the TOML command shims for Gemini CLI and generic/Antigravity hosts from the
// canonical Markdown commands in .claude/commands/. Run with --check in CI to fail when a
// generated file has drifted from its source.

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const SRC = path.join(ROOT, '.claude', 'commands');
const TARGETS = [path.join(ROOT, '.gemini', 'commands'), path.join(ROOT, 'commands')];

const HEADER = '# Generated by scripts/build-commands.js from .claude/commands/. Do not edit.\n';

function parse(file) {
  const raw = fs.readFileSync(file, 'utf8');
  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/);
  if (!match) throw new Error(`${path.basename(file)}: missing frontmatter`);
  const [, front, body] = match;
  const description = (front.match(/^description:\s*(.+)$/m) || [])[1];
  if (!description) throw new Error(`${path.basename(file)}: missing description`);
  return { description: description.trim(), body: body.trim() };
}

function toToml({ description, body }) {
  const prompt = body.replace(/\$ARGUMENTS/g, '{{args}}');
  if (prompt.includes('"""')) throw new Error('command body contains a TOML triple quote');
  return `${HEADER}description = ${JSON.stringify(description)}\n\nprompt = """\n${prompt}\n"""\n`;
}

const check = process.argv.includes('--check');
const files = fs.readdirSync(SRC).filter((f) => f.endsWith('.md')).sort();
let drift = 0;

for (const dir of TARGETS) fs.mkdirSync(dir, { recursive: true });

for (const file of files) {
  const toml = toToml(parse(path.join(SRC, file)));
  const name = file.replace(/\.md$/, '.toml');
  for (const dir of TARGETS) {
    const out = path.join(dir, name);
    const existing = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : null;
    if (existing === toml) continue;
    if (check) {
      console.error(`drift: ${path.relative(ROOT, out)}`);
      drift++;
    } else {
      fs.writeFileSync(out, toml);
    }
  }
}

// Remove shims whose source command was deleted.
const expected = new Set(files.map((f) => f.replace(/\.md$/, '.toml')));
for (const dir of TARGETS) {
  for (const stale of fs.readdirSync(dir).filter((f) => f.endsWith('.toml') && !expected.has(f))) {
    const out = path.join(dir, stale);
    if (check) {
      console.error(`orphan: ${path.relative(ROOT, out)}`);
      drift++;
    } else {
      fs.unlinkSync(out);
    }
  }
}

if (check && drift) {
  console.error(`\n${drift} generated command file(s) out of date. Run: node scripts/build-commands.js`);
  process.exit(1);
}

console.log(check ? `commands: ${files.length} in sync` : `commands: wrote ${files.length} x ${TARGETS.length} shims`);
